for i in range(len(row_idx)):
    u_ = row_idx[i]
    for j in range(len(col_idx)):
        v = col_idx[j]
        if u_ == -1 or v == -1:
            # GH#47171 note: numpy's negative indexing would wrap around
            #  to the last element, which is not what we want here.
            if fill_value is not None:
                out[i, j] = fill_value
        else:
            out[i, j] = arr[u_, v]
